struct sk_buff *fragment_udp_packet(struct sk_buff *skb, u32 features)
{
    int mss = skb->dev->mtu - sizeof(struct ipv6hdr) - sizeof(struct udphdr);
    struct iphdr *ip_header = ip_hdr(skb);
    struct udphdr *udp_header = udp_hdr(skb);

    if (skb->len <= mss)
        return skb;

    if (!(features & NETIF_F_IPV6_CSUM) && !skb_is_gso(skb)) {
        udp_header->check = 0;
        udp_header->check = csum_tcpudp_magic(ip_header->saddr, ip_header->daddr,
                                              skb->len - sizeof(struct udphdr),
                                              IPPROTO_UDP, skb_checksum(skb, 0, skb->len, 0));
    }

    skb->transport_header += sizeof(struct udphdr);
    skb->network_header += sizeof(struct ipv6hdr);
    skb = ip6_fragment(skb, features);
    return skb;
}

struct sk_buff *fragment_udp_ipv6_packet(struct sk_buff *skb, u32 features)
{
    int mss = skb->dev->mtu - sizeof(struct ipv6hdr) - sizeof(struct udphdr);
    struct iphdr *ip_header;
    struct udphdr *udp_header;

    if (skb->len <= mss)
        return skb;

    ip_header = ip_hdr(skb);
    udp_header = udp_hdr(skb);

    if (!skb_is_valid(skb))
        return ERR_PTR(-EINVAL);

    if (!skb_checksum_help(skb))
        return ERR_PTR(-EINVAL);

    skb_reset_transport_header(skb);
    skb_set_network_header(skb, skb->data - ip_header);

    if (skb_push(skb, sizeof(struct frag_hdr)) == NULL)
        return ERR_PTR(-ENOMEM);

    skb->protocol = htons(ETH_P_IPV6);

    return skb_segment(skb, features);
}

struct sk_buff *fragment_udp_ipv6_packet(struct sk_buff *skb, u32 features) {
    if (!skb || skb->len <= dev->mtu) {
        return ERR_PTR(-EINVAL);
    }

    if (!(features & NETIF_F_FRAGLIST)) {
        return ERR_PTR(-EOPNOTSUPP);
    }

    skb_checksum_help(skb);
    skb_pull(skb, skb_network_header(skb) - skb->data);

    if (skb_unsplit(skb, features)) {
        return ERR_PTR(-ENOMEM);
    }

    return skb;
}

struct sk_buff *fragment_udp_packet(struct sk_buff *skb, u32 features)
{
    unsigned int mss = skb->dev->mtu - sizeof(struct ipv6hdr) - sizeof(struct udphdr);
    struct udphdr *uh = udp_hdr(skb);
    int err;

    if (skb->len <= mss)
        return skb;

    if (skb_is_gso(skb)) {
        if (skb_gso_segment(skb, features))
            return ERR_PTR(-EINVAL);
        return skb;
    }

    if (!skb_is_gso(skb)) {
        skb->csum = 0;
        uh->check = 0;
        skb->ip_summed = CHECKSUM_NONE;
        skb->csum = csum_tcpudp_nofold(skb->network_header, skb->transport_header, skb->len, IPPROTO_UDP, skb->csum);
        skb->ip_summed = CHECKSUM_PARTIAL;
    }

    skb = skb_share_check(skb, GFP_ATOMIC);
    if (!skb)
        return ERR_PTR(-ENOMEM);

    skb->transport_header = skb->network_header + sizeof(struct ipv6hdr);
    skb->csum_start = skb_transport_header(skb) - skb->head;

    skb = skb_fragment(skb, mss, features, &err);
    if (IS_ERR(skb))
        return skb;

    if (skb->ip_summed == CHECKSUM_NONE) {
        uh->check = 0;
        skb->csum = csum_tcpudp_nofold(skb_network_header(skb), skb_transport_header(skb), skb->len, IPPROTO_UDP, 0);
        skb->ip_summed = CHECKSUM_PARTIAL;
    }

    return skb;
}
